CREATE PROCEDURE public.get_mission_data(IN mission_id integer)
    LANGUAGE plpgsql
    AS $$
    DECLARE
    BEGIN
        SELECT * FROM TELEMETRY_RECORDS
                 WHERE RECORD_MISSION_ID = MISSION_ID;
    END;
$$;


